INSERT INTO `news` (`id`, `slug`, `title_en`, `title_bn`, `published_date`, `summary`, `content`, `image_url`, `is_featured`, `is_active`, `created_at`) VALUES ('1', 'admission-fair-opening-2026', 'Grand Opening of Admission Fair Fall 2026 at RMU', '', '2026-09-30', 'The Fall 2026 admission fair kicked off with wide participation from prospective students, parents, and academic counselors at the Kushtia campus.', '<p>The Fall 2026 admission fair was formally inaugurated by university leadership. The Vice-Chancellor emphasized the university commitment to quality education, state-of-the-art laboratory facilities, and affordable tuition with merit-based waivers. Numerous students enrolled on the first day across CSE, EEE, BBA, English, and Agriculture.</p>', NULL, '1', '1', '2026-10-17 12:39:47');
INSERT INTO `news` (`id`, `slug`, `title_en`, `title_bn`, `published_date`, `summary`, `content`, `image_url`, `is_featured`, `is_active`, `created_at`) VALUES ('2', 'research-symposium-held', 'International Seminar on Sustainable Agricultural Innovations', '', '2026-09-12', 'Faculty of Agriculture hosted researchers and agricultural specialists to discuss modern climate-resilient farming techniques.', '<p>A seminar on climate adaptation in rural farming was successfully hosted by the Department of Agriculture at Rabindra Maitree University. Keynote speakers presented findings on soil conservation, smart irrigation, and high-yield bio-fortified crop varieties.</p>', NULL, '0', '1', '2026-10-17 12:39:47');
INSERT INTO `news` (`id`, `slug`, `title_en`, `title_bn`, `published_date`, `summary`, `content`, `image_url`, `is_featured`, `is_active`, `created_at`) VALUES ('3', 'ugc-academic-accreditation-visit', 'UGC High-Powered Delegation Commends RMU Campus Infrastructure', '', '2026-08-14', 'Delegates from the University Grants Commission visited laboratory facilities, library resources, and digital classrooms at RMU Kushtia.', '<p>During an official inspection, UGC representatives praised the modern campus infrastructure, expansive seminar library, and well-equipped engineering labs of Rabindra Maitree University, reaffirming UGC regulatory compliance and academic standards.</p>', NULL, '0', '1', '2026-10-17 12:39:47');
INSERT INTO `notices` (`id`, `slug`, `title_en`, `title_bn`, `category`, `content`, `file_path`, `published_date`, `is_pinned`, `is_active`, `view_count`, `created_at`) VALUES ('1', 'admission-fair-fall-2026', 'Grand Opening of Admission Fair Fall 2026 at RMU', '', 'Admission', '<p>The Grand Opening of the Fall 2026 Semester Admission Fair was held with great enthusiasm at Rabindra Maitree University. During the admission fair, special waivers on admission fees and tuition fees are being offered across all undergraduate and postgraduate programs. All prospective students are cordially invited to visit the Kushtia campus or apply directly online.</p><p>Admission Hotline: +8801302991188 | Email: admission@rmu.ac.bd</p>', 'downloads/admission_fair_circular.pdf', '2026-09-30', '1', '1', '468', '2026-10-17 12:39:47');
INSERT INTO `notices` (`id`, `slug`, `title_en`, `title_bn`, `category`, `content`, `file_path`, `published_date`, `is_pinned`, `is_active`, `view_count`, `created_at`) VALUES ('2', 'mansur-ali-scholarship', 'Notice: Mansur Ali and Atharunnesa Trust Scholarship', '', 'Scholarship', '<p>Applications are invited from meritorious and economically challenged regular students of Rabindra Maitree University for the Mansur Ali and Atharunnesa Trust Scholarship Fund. Interested students must submit the completed application form along with academic transcripts and family income certificates to the Registrar Office by November 15, 2026.</p>', 'downloads/scholarship_form.pdf', '2026-09-15', '1', '1', '218', '2026-10-17 12:39:47');
INSERT INTO `notices` (`id`, `slug`, `title_en`, `title_bn`, `category`, `content`, `file_path`, `published_date`, `is_pinned`, `is_active`, `view_count`, `created_at`) VALUES ('3', 'fazli-hossain-scholarship', 'Mohammad Fazli Hossain Memorial Trust Scholarship Circular', '', 'Scholarship', '<p>The Mohammad Fazli Hossain Memorial Trust Fund Scholarship will be awarded to students who achieve the highest CGPA in the faculties of Science, Engineering, and Arts. Eligible students must submit their applications through their respective department heads.</p>', NULL, '2026-08-20', '0', '1', '185', '2026-10-17 12:39:47');
INSERT INTO `notices` (`id`, `slug`, `title_en`, `title_bn`, `category`, `content`, `file_path`, `published_date`, `is_pinned`, `is_active`, `view_count`, `created_at`) VALUES ('4', 'hamim-khan-award', 'Notice Regarding Hamim Khan Memorial Cultural Award', '', 'Academic', '<p>The Hamim Khan Memorial Award will be conferred upon students in recognition of outstanding contributions to literature, visual arts, and cultural activities at the university. For detailed submission guidelines, please contact the Registrar Office.</p>', NULL, '2026-07-12', '0', '1', '142', '2026-10-17 12:39:47');
INSERT INTO `notices` (`id`, `slug`, `title_en`, `title_bn`, `category`, `content`, `file_path`, `published_date`, `is_pinned`, `is_active`, `view_count`, `created_at`) VALUES ('5', 'mujibnagar-day-celebration', 'Celebration of Historic Mujibnagar Day at RMU Campus', '', 'General', '<p>The Historic Mujibnagar Day will be observed with due solemnity at Rabindra Maitree University Kushtia Campus. All faculty members, students, officers, and staff are requested to attend the commemorative seminar at the Central Auditorium.</p>', NULL, '2026-04-16', '0', '1', '195', '2026-10-17 12:39:47');
INSERT INTO `programs` (`id`, `department_id`, `slug`, `title_en`, `title_bn`, `degree_level`, `degree_type`, `duration`, `duration_years`, `total_semesters`, `total_credits`, `semester_credits_json`, `eligibility`, `description`, `tuition_fee`, `sort_order`, `is_active`, `created_at`) VALUES ('1', '6', 'bsc-in-cse', 'Computer Science and Engineering (CSE)', '', 'Undergraduate', 'Bachelor / Honours', '4 Years (8 Semesters)', '4.0', '8', '148', NULL, 'Minimum GPA 2.50 in both SSC & HSC with Science background and Mathematics.', 'Comprehensive undergraduate engineering degree covering algorithms, systems, software engineering, databases, and AI.', 'BDT 3,80,000 (Waiver up to 50% available)', '7', '1', '2026-10-17 12:39:47');
